const db=()=>{if(!supabase)throw new Error('Supabase n’est pas configuré.');return supabase}
const fail=(error:{message:string}|null)=>{if(error)throw new Error(error.message)}
const queryCache=new Map<string,{until:number,value:unknown}>()
async function cached<T>(key:string,loader:()=>Promise<T>,ttl=45_000):Promise<T>{const hit=queryCache.get(key);if(hit&&hit.until>Date.now())return hit.value as T;const pending=loader();queryCache.set(key,{until:Date.now()+ttl,value:pending});try{const value=await pending;queryCache.set(key,{until:Date.now()+ttl,value});return value}catch(error){queryCache.delete(key);throw error}}
const invalidate=(...keys:string[])=>keys.forEach(key=>queryCache.delete(key))
async function invokeEdge<T>(name:string,body?:Record<string,unknown>,retryNetwork=false):Promise<T>{
  const client=db();
  for(let attempt=0;attempt<(retryNetwork?2:1);attempt+=1){
    const {data,error}=await client.functions.invoke(name,{body});
    if(!error)return data as T;
    let message=error.message;
    const context=(error as {context?:Response}).context;
    if(context)try{const detail=await context.clone().json() as {error?:string};message=detail.error||message}catch{/* réponse non JSON */}
    const transient=!context&&/failed to send|fetch|network|connexion/i.test(message);
    if(!transient||attempt===1)throw new Error(transient?'Connexion instable : impossible de joindre le briefing. Réessayez dans quelques secondes.':message);
  }
  throw new Error('Briefing indisponible');
}

export async function signIn(email:string,password:string){
  const client=db();
  const {data,error}=await client.auth.signInWithPassword({email,password});
  if(error){
    const message=error.message.toLowerCase();
    if(message.includes('email not confirmed')) throw new Error('Adresse e-mail non confirmée. Demandez un nouveau lien de confirmation.');
    if(message.includes('invalid login credentials')) throw new Error('E-mail ou mot de passe incorrect. Si vous venez de vous inscrire, confirmez d’abord le lien reçu par e-mail.');
    throw new Error(error.message);
  }
  if(!data.user)return data;
  const {data:profile, error:profileError}=await client.from('profiles').select('active,access_expires_at').eq('id',data.user.id).single();
  if(profileError){await client.auth.signOut();throw new Error('Profil utilisateur introuvable.');}
  if(!profile.active){await client.auth.signOut();throw new Error('Ce compte est suspendu. Contactez le Super Admin.');}
  // An expired SaaS trial stays signed in so the workspace remains readable.
  return data;
}
export async function signUpWithPassword(input:{email:string;password:string;fullName:string;companyName:string;referralCode?:string}){
  const redirectTo=new URL(import.meta.env.BASE_URL,location.origin);redirectTo.hash='app';
  const {data,error}=await db().auth.signUp({email:input.email,password:input.password,options:{emailRedirectTo:redirectTo.href,data:{name:input.fullName,full_name:input.fullName,company_name:input.companyName,trial_hours:72,referral_code:input.referralCode||null}}});
  fail(error);return data
}
