export async function uploadProfileAvatar(profileId:string,file:File){
  if(!file.type.startsWith('image/'))throw new Error('Choisissez une image pour la photo du collaborateur.')
  if(file.size>5*1024*1024)throw new Error('La photo doit peser moins de 5 Mo.')
  const ext=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'')||'jpg'
  const path=`profiles/${profileId}/${crypto.randomUUID()}.${ext}`
  const {error}=await db().storage.from('avatars').upload(path,file,{upsert:false,contentType:file.type});fail(error)
  const {data,error:signError}=await db().storage.from('avatars').createSignedUrl(path,60*60*24*365);fail(signError)
  if(!data)throw new Error('Photo indisponible')
  return data.signedUrl
}
