export async function getCompanySettings():Promise<CompanySettings|null>{const {data,error}=await db().from('company_profile').select('*').limit(1).maybeSingle();fail(error);return data as CompanySettings|null}
export async function updateCompanySettings(input:Partial<CompanySettings>){const current=await getCompanySettings();const query=current?db().from('company_profile').update(input).eq('id',current.id):db().from('company_profile').insert(input);const {data,error}=await query.select().single();fail(error);return data as CompanySettings}
export async function getAppSetting<T=unknown>(key:string):Promise<T|null>{const {data,error}=await db().from('app_settings').select('value').eq('key',key).maybeSingle();fail(error);return (data?.value??null) as T|null}
export async function saveAppSetting(key:string,value:unknown){const client=db(),{data:{user}}=await client.auth.getUser();if(!user)throw new Error('Session expirée');const {data:profile,error:profileError}=await client.from('profiles').select('tenant_owner_id').eq('id',user.id).single();fail(profileError);const {data,error}=await client.from('app_settings').upsert({key,value,tenant_owner_id:profile?.tenant_owner_id||user.id,updated_by:user.id,updated_at:new Date().toISOString()},{onConflict:'tenant_owner_id,key'}).select().single();fail(error);return data}
