export async function listCampaigns():Promise<Campaign[]>{const enhanced=await db().from('campaigns').select('*,clients(name),communication_templates(subject,body)').order('created_at',{ascending:false});if(!enhanced.error)return enhanced.data as Campaign[];const fallback=await db().from('campaigns').select('*,communication_templates(subject,body)').order('created_at',{ascending:false});fail(fallback.error);return fallback.data as Campaign[]}
export async function updateCampaignApproval(id:string,approval_status:'A_VALIDER'|'APPROUVE'|'REJETE'){const {data,error}=await db().from('campaigns').update({approval_status,approved_at:approval_status==='APPROUVE'?new Date().toISOString():null,status:approval_status==='APPROUVE'?'QUEUED':'DRAFT'}).eq('id',id).select('*,clients(name),communication_templates(subject,body)').single();fail(error);return data as Campaign}
export async function createCampaign(input:{name:string;channel:'SMS'|'EMAIL';subject?:string;message:string;recipients:string[];scheduled_at?:string|null;send_now?:boolean;scope?:'MARCEL'|'CLIENT';client_id?:string|null;objective?:string;approval_status?:'BROUILLON'|'A_VALIDER'|'APPROUVE';template_id?:string|null}){const client=db(),{data:{user}}=await client.auth.getUser();if(!user)throw new Error('Session expirée');let templateId=input.template_id||null;if(!templateId){const {data:template,error:templateError}=await client.from('communication_templates').insert({channel:input.channel,name:input.name,subject:input.subject||null,body:input.message}).select().single();fail(templateError);templateId=template.id}const approval=input.approval_status|| (input.send_now?'APPROUVE':'A_VALIDER');const enhancedPayload={name:input.name,channel:input.channel,template_id:templateId,status:approval==='APPROUVE'?'QUEUED':'DRAFT',approval_status:approval,scope:input.scope||'MARCEL',client_id:input.client_id||null,objective:input.objective||null,scheduled_at:input.send_now?new Date().toISOString():input.scheduled_at,recipient_count:input.recipients.length,created_by:user.id,approved_at:approval==='APPROUVE'?new Date().toISOString():null};let created=await client.from('campaigns').insert(enhancedPayload).select().single();if(created.error)created=await client.from('campaigns').insert({name:input.name,channel:input.channel,template_id:templateId,status:input.send_now?'QUEUED':'DRAFT',scheduled_at:input.send_now?new Date().toISOString():input.scheduled_at,recipient_count:input.recipients.length,created_by:user.id}).select().single();fail(created.error);const {data:campaign}=created;const {error:recipientsError}=await client.from('campaign_recipients').insert(input.recipients.map(address=>({campaign_id:campaign.id,address,status:'QUEUED'})));fail(recipientsError);if(input.send_now&&approval==='APPROUVE')await invokeEdge('campaign-dispatch',{campaign_id:campaign.id});return campaign as Campaign}
export async function listCallLogs():Promise<CallLog[]>{const {data,error}=await db().from('call_logs').select('*').order('created_at',{ascending:false}).limit(100);fail(error);return data as CallLog[]}
export async function startCall(input:{contact_type:'PROSPECT'|'CLIENT'|'CALL_LIST';contact_id:string;phone:string}){const client=db(),{data:{user}}=await client.auth.getUser();if(!user)throw new Error('Session expirée');const {data,error}=await client.from('call_logs').insert({...input,status:'DIALING',provider:'NATIVE_DIALER',consent_confirmed:true,initiated_by:user.id}).select().single();fail(error);if(input.contact_type==='CALL_LIST')await client.from('call_list_contacts').update({status:'DIALING',last_called_at:new Date().toISOString()}).eq('id',input.contact_id);return data as CallLog}
export async function finishCall(id:string,input:{status:string;outcome:string;notes:string;duration_seconds?:number;appointment_at?:string|null}){const client=db(),{data:current,error:currentError}=await client.from('call_logs').select('contact_type,contact_id').eq('id',id).single();fail(currentError);const {data,error}=await client.from('call_logs').update({status:input.status,outcome:input.outcome,notes:input.notes,duration_seconds:input.duration_seconds,ended_at:new Date().toISOString()}).eq('id',id).select().single();fail(error);if(current?.contact_type==='CALL_LIST'&&current.contact_id){const nextStatus=input.outcome.includes('RENDEZ-VOUS ACCEPTÉ')?'APPOINTMENT':input.outcome==='À RELANCER'||input.outcome==='INJOIGNABLE'?'CALLBACK':'CALLED';const {data:contact}=await client.from('call_list_contacts').select('attempts,total_call_seconds').eq('id',current.contact_id).single();await client.from('call_list_contacts').update({status:nextStatus,outcome:input.outcome,notes:input.notes,appointment_at:input.appointment_at||null,attempts:Number(contact?.attempts||0)+1,total_call_seconds:Number(contact?.total_call_seconds||0)+Number(input.duration_seconds||0),last_called_at:new Date().toISOString()}).eq('id',current.contact_id)}return data as CallLog}
