export async function createContactGroup(input:{name:string;description?:string;members:Array<{name:string;phone?:string;email?:string;company?:string;tags?:string}>}){const client=db(),{data:{user}}=await client.auth.getUser();if(!user)throw new Error('Session expirée');const {data:group,error}=await client.from('contact_groups').insert({name:input.name,description:input.description||null,created_by:user.id}).select().single();fail(error);if(input.members.length){const {error:membersError}=await client.from('contact_group_members').insert(input.members.map(member=>({group_id:group.id,name:member.name||'Sans nom',phone:member.phone||null,email:member.email||null,company:member.company||null,tags:member.tags||null,marketing_opt_in:true})));fail(membersError)}return group as ContactGroup}
export async function listCallLists():Promise<CallList[]>{const {data,error}=await db().from('call_lists').select('*,call_list_contacts(count)').order('created_at',{ascending:false});fail(error);return data as CallList[]}
export async function listCallListContacts(callListId:string):Promise<CallListContact[]>{const {data,error}=await db().from('call_list_contacts').select('*').eq('call_list_id',callListId).order('created_at');fail(error);return data as CallListContact[]}
export async function createCallList(input:{name:string;source_filename:string;contacts:Array<{name:string;phone:string;email?:string;company?:string}>}){const client=db(),{data:{user}}=await client.auth.getUser();if(!user)throw new Error('Session expirée');const {data:list,error}=await client.from('call_lists').insert({name:input.name,source_filename:input.source_filename,created_by:user.id}).select().single();fail(error);const usable=input.contacts.filter(contact=>contact.phone);if(!usable.length)throw new Error('Le fichier ne contient aucun numéro à appeler.');const {error:contactsError}=await client.from('call_list_contacts').insert(usable.map(contact=>({call_list_id:list.id,name:contact.name||'Sans nom',phone:contact.phone,email:contact.email||null,company:contact.company||null})));fail(contactsError);return list as CallList}
