export async function createQuote(input:{client_id:string;project_id?:string;valid_until:string;currency:string;discount:number;items:InvoiceItem[]}):Promise<Quote>{const {data,error}=await db().rpc('create_quote_with_items',{p_client_id:input.client_id,p_project_id:input.project_id||null,p_valid_until:input.valid_until,p_currency:input.currency,p_discount:input.discount,p_items:input.items});fail(error);if(!data)throw new Error('La création n’a renvoyé aucun numéro. Vérifiez la liste avant de réessayer.');invalidate('quotes');const {data:quote,error:readError}=await db().from('quotes').select('*,clients(name,email,address),projects(name),quote_items(*)').eq('id',data).single();if(readError)throw new Error(`Le devis a été créé, mais son affichage a échoué (${readError.message}). Actualisez la liste avant de réessayer pour éviter un doublon.`);return quote as Quote}
