export async function uploadEditorialAsset(file:File){const ext=file.name.split('.').pop()||'bin',path=`${crypto.randomUUID()}.${ext}`;const {error}=await db().storage.from('editorial-assets').upload(path,file,{upsert:false});fail(error);const {data,error:signError}=await db().storage.from('editorial-assets').createSignedUrl(path,60*60*24*365);fail(signError);if(!data)throw new Error('Lien du fichier indisponible');return data.signedUrl}
