const portalMessage=(row:{id:string;client_id:string;sender_id:string;body:string;created_at:string;profiles?:{full_name:string}[]|{full_name:string}|null}):ClientPortalMessage=>({...row,profiles:Array.isArray(row.profiles)?row.profiles[0]||null:row.profiles||null})
export async function listClientPortalMessages(clientId:string):Promise<ClientPortalMessage[]>{const {data,error}=await db().from('client_portal_messages').select('id,client_id,sender_id,body,created_at,profiles(full_name)').eq('client_id',clientId).order('created_at',{ascending:true}).limit(200);fail(error);return (data||[]).map(portalMessage)}
export async function sendClientPortalMessage(clientId:string,body:string):Promise<ClientPortalMessage>{const {data:{user},error:authError}=await db().auth.getUser();fail(authError);if(!user)throw new Error('Session expirée');const value=body.trim();if(!value||value.length>4000)throw new Error('Le message doit contenir entre 1 et 4 000 caractères.');const {data,error}=await db().from('client_portal_messages').insert({client_id:clientId,sender_id:user.id,body:value}).select('id,client_id,sender_id,body,created_at,profiles(full_name)').single();fail(error);if(!data)throw new Error('Message non enregistré');return portalMessage(data)}
export async function listTeamChatMessages():Promise<TeamChatMessage[]>{const {data,error}=await db().from('team_chat_messages').select('id,sender_id,body,created_at,profiles(full_name)').order('created_at',{ascending:true}).limit(200);fail(error);return (data||[]).map(row=>({...row,profiles:Array.isArray(row.profiles)?row.profiles[0]||null:row.profiles||null}))}
export async function sendTeamChatMessage(body:string):Promise<TeamChatMessage>{const {data:{user},error:authError}=await db().auth.getUser();fail(authError);if(!user)throw new Error('Session expirée');const value=body.trim();if(!value||value.length>4000)throw new Error('Le message doit contenir entre 1 et 4 000 caractères.');const {data,error}=await db().from('team_chat_messages').insert({sender_id:user.id,body:value}).select('id,sender_id,body,created_at,profiles(full_name)').single();fail(error);if(!data)throw new Error('Message non enregistré');return {...data,profiles:Array.isArray(data.profiles)?data.profiles[0]||null:data.profiles||null}}
export async function getMyClientPortal():Promise<ClientPortalWorkspace>{const {data:{user}}=await db().auth.getUser();if(!user)throw new Error('Session expirée');const {data:access,error}=await db().from('client_portal_access').select('*').eq('profile_id',user.id).eq('active',true).single();fail(error);const clientId=access.client_id;const [client,projects,editorial,invoices,approvals]=await Promise.all([db().from('clients').select('*').eq('id',clientId).single(),db().from('projects').select('*,clients(name)').eq('client_id',clientId).order('created_at',{ascending:false}),db().from('editorial_items').select('*,clients(name),projects(name)').eq('client_id',clientId).order('publish_at',{ascending:true}),db().from('invoices').select('*,clients(name,email,address),projects(name),invoice_items(*),payments(*)').eq('client_id',clientId).order('created_at',{ascending:false}),db().from('creative_approvals').select('*,editorial_items(title),creative_feedback(*,profiles(full_name))').eq('client_id',clientId).order('created_at',{ascending:false})]);fail(client.error);fail(projects.error);fail(editorial.error);fail(invoices.error);fail(approvals.error);return {access:access as PortalAccess,client:client.data as Client,projects:projects.data as Project[],editorial:editorial.data as EditorialItem[],invoices:invoices.data as Invoice[],approvals:approvals.data as CreativeApproval[]}}
